import React, { useState, useEffect } from 'react';
import { Database, Cpu, Radio, Server, Activity, Clock } from 'lucide-react';

const SystemStatusBar = () => {
  const [timeStr, setTimeStr] = useState(new Date().toLocaleTimeString());

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeStr(new Date().toLocaleTimeString());
    }, 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div
      style={{
        background: 'linear-gradient(135deg, #07202c 0%, #0a2735 100%)',
        color: '#EBF4F6',
        borderRadius: 'var(--radius-md)',
        padding: '0.75rem 1.25rem',
        marginBottom: '1.5rem',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        flexWrap: 'wrap',
        gap: '0.85rem',
        boxShadow: '0 4px 18px rgba(8, 131, 149, 0.15)',
        border: '1px solid rgba(122, 178, 178, 0.2)',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
        <span
          style={{
            width: '10px',
            height: '10px',
            borderRadius: '50%',
            background: '#10b981',
            boxShadow: '0 0 10px #10b981',
            animation: 'pulse 1.5s infinite',
          }}
        />
        <span style={{ fontSize: '0.85rem', fontWeight: '800', letterSpacing: '0.5px' }}>
          INDUSTRIAL DIGITAL TWIN CONTROL SYSTEM
        </span>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '1.25rem', flexWrap: 'wrap', fontSize: '0.78rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Database size={14} style={{ color: '#10b981' }} />
          <span style={{ color: '#7AB2B2', fontWeight: '700' }}>MongoDB:</span>
          <span style={{ color: '#ffffff', fontWeight: '800' }}>Connected</span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Cpu size={14} style={{ color: '#10b981' }} />
          <span style={{ color: '#7AB2B2', fontWeight: '700' }}>AI Engine:</span>
          <span style={{ color: '#ffffff', fontWeight: '800' }}>Running</span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Radio size={14} style={{ color: '#10b981' }} />
          <span style={{ color: '#7AB2B2', fontWeight: '700' }}>MQTT Broker:</span>
          <span style={{ color: '#ffffff', fontWeight: '800' }}>Connected</span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Server size={14} style={{ color: '#10b981' }} />
          <span style={{ color: '#7AB2B2', fontWeight: '700' }}>REST API:</span>
          <span style={{ color: '#ffffff', fontWeight: '800' }}>Online</span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Activity size={14} style={{ color: '#088395' }} />
          <span style={{ color: '#7AB2B2', fontWeight: '700' }}>Connected Sensors:</span>
          <span style={{ color: '#ffffff', fontWeight: '800', fontFamily: 'JetBrains Mono' }}>136 Feeds</span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', background: 'rgba(255, 255, 255, 0.08)', padding: '0.2rem 0.6rem', borderRadius: '4px' }}>
          <Clock size={13} style={{ color: '#7AB2B2' }} />
          <span style={{ color: '#EBF4F6', fontFamily: 'JetBrains Mono', fontWeight: '700' }}>{timeStr}</span>
        </div>
      </div>
    </div>
  );
};

export default SystemStatusBar;
